										</span>
									</div>
									<div className="form-ctl">
										<select
											className="input mono"
											data-testid="slot-hw-device"
											value={device}
											onChange={(e) => setDevice(e.target.value)}
										>
											{/* keep an out-of-vocab persisted device selectable */}
											{device && !devices.some((d) => d.id === device) && (
