											release
										</span>
									</div>
									<div className="form-ctl">
										<input
											className={
												"input mono" + (fieldErrs.imagePin ? " input-err" : "")
											}
											data-testid="slot-hw-image-pin"
											value={imagePin}
											onChange={(e) => {
												setImagePin(e.target.value);
												setFieldErrs((p) => ({ ...p, imagePin: undefined }));
											}}
											placeholder="release default — e.g. ghcr.io/owner/repo:tag"
											spellCheck={false}
										/>
										{fieldErrs.imagePin ? (
											<div className="hint" style={{ color: "var(--err)" }}>
												{fieldErrs.imagePin}
											</div>
										) : (
											<div className="hint">
												Pin a custom image to test a build or roll back. Empty =
												use the default release.
											</div>
										)}
									</div>
								</div>

								<div className="form-row">
									<div className="form-lbl">
										<span>Profile</span>
										<span className="sub">
											⟳ Which runner build to use. Empty = auto-detect from
											device.
										</span>
									</div>
									<div className="form-ctl">
										<select
											className={"input mono" + (fitWarn ? " input-err" : "")}
											data-testid="slot-hw-binary"
											value={binary}
											onChange={(e) => setBinary(e.target.value)}
										>
											<option value="">— default (from device) —</option>
											{/* keep an out-of-vocab persisted binary selectable */}
											{binary && !binaryKeys.includes(binary) && (
												<option value={binary}>{binary}</option>
											)}
											{binaryKeys.map((k) => (
												<option key={k} value={k}>
													{k}
													{backends[k]?.backend
														? ` · ${backends[k].backend}`
														: ""}
												</option>
											))}
										</select>
										{fitWarn && (
											<div
												className="hint"
												data-testid="slot-hw-fit-warning"
												style={{
													marginTop: 6,
													padding: "6px 10px",
													borderRadius: "var(--rad-sm)",
													color: "var(--warn)",
													border: "1px solid var(--warn-line)",
													background: "var(--warn-soft)",
												}}
											>
												⚠ {fitWarn}
											</div>
										)}
									</div>
								</div>

								<div className="form-row">
									<div className="form-lbl">
										<span>Threads</span>
										<span className="sub">
											CPU thread count for the runner. 0 = let the runtime
											decide.
										</span>
									</div>
