												setFieldErrs((p) => ({ ...p, threads: undefined }));
											}}
											placeholder="0"
											inputMode="numeric"
										/>
										{fieldErrs.threads && (
											<div className="hint" style={{ color: "var(--err)" }}>
												{fieldErrs.threads}
											</div>
										)}
									</div>
								</div>

								<div className="form-row">
									<div className="form-lbl">
										<span>Ngl</span>
										<span className="sub">
											GPU layers to offload. -1 = all layers, 0 = CPU only.
										</span>
									</div>
									<div className="form-ctl">
										<input
											className={
												"input mono" + (fieldErrs.ngl ? " input-err" : "")
											}
											data-testid="slot-hw-ngl"
											value={nGpuLayers}
											onChange={(e) => {
												setNGpuLayers(e.target.value);
												setFieldErrs((p) => ({ ...p, ngl: undefined }));
											}}
											placeholder="-1"
											inputMode="numeric"
										/>
										{fieldErrs.ngl && (
											<div className="hint" style={{ color: "var(--err)" }}>
												{fieldErrs.ngl}
											</div>
										)}
									</div>
								</div>
							</>
						);
					})()}

